/**
 * Bundled standalone Canvas-based Chart library.
 * Compatible with Chart.js 3/4 subset: doughnut, pie, bar, line.
 * Offline, zero-dependency, high-DPI crisp rendering.
 */
(function(global) {
    class Chart {
        constructor(canvas, config) {
            this.canvas = typeof canvas === 'string' ? document.getElementById(canvas) : canvas;
            if (!this.canvas) return;
            this.ctx = this.canvas.getContext('2d');
            this.config = config || {};
            this.type = config.type || 'bar';
            this.data = config.data || { labels: [], datasets: [] };
            this.options = config.options || {};
            
            // Handle DPI
            this.resize();
            this.render();
            
            this._onResize = () => {
                this.resize();
                this.render();
            };
            window.addEventListener('resize', this._onResize);
        }

        resize() {
            const rect = this.canvas.getBoundingClientRect();
            const dpr = window.devicePixelRatio || 1;
            const w = rect.width || 300;
            const h = rect.height || 220;
            this.canvas.width = w * dpr;
            this.canvas.height = h * dpr;
            this.ctx.scale(dpr, dpr);
            this.width = w;
            this.height = h;
        }

        destroy() {
            window.removeEventListener('resize', this._onResize);
            if (this.ctx) {
                this.ctx.clearRect(0, 0, this.width || 300, this.height || 220);
            }
        }

        update() {
            this.render();
        }

        render() {
            const ctx = this.ctx;
            if (!ctx) return;
            ctx.clearRect(0, 0, this.width, this.height);

            if (this.type === 'doughnut' || this.type === 'pie') {
                this.renderPie(this.type === 'doughnut');
            } else if (this.type === 'line') {
                this.renderLine();
            } else {
                this.renderBar();
            }
        }

        renderPie(isDoughnut) {
            const ctx = this.ctx;
            const labels = this.data.labels || [];
            const dataset = (this.data.datasets && this.data.datasets[0]) || { data: [] };
            const data = dataset.data || [];
            const colors = dataset.backgroundColor || ['#0B1F4A', '#00B4D8', '#1B7A6B', '#E8960C', '#E63946', '#6C757D', '#9B5DE5'];
            
            const total = data.reduce((sum, v) => sum + (Number(v) || 0), 0);
            if (total === 0) {
                ctx.fillStyle = '#666';
                ctx.font = '13px monospace';
                ctx.textAlign = 'center';
                ctx.fillText('No data available', this.width / 2, this.height / 2);
                return;
            }

            const centerX = this.width / 2;
            const centerY = (this.height - 35) / 2;
            const radius = Math.min(centerX, centerY) - 15;
            const innerRadius = isDoughnut ? radius * 0.55 : 0;

            let startAngle = -Math.PI / 2;
            for (let i = 0; i < data.length; i++) {
                const val = Number(data[i]) || 0;
                if (val <= 0) continue;
                const sliceAngle = (val / total) * 2 * Math.PI;
                const endAngle = startAngle + sliceAngle;

                ctx.beginPath();
                ctx.arc(centerX, centerY, radius, startAngle, endAngle);
                if (isDoughnut) {
                    ctx.arc(centerX, centerY, innerRadius, endAngle, startAngle, true);
                } else {
                    ctx.lineTo(centerX, centerY);
                }
                ctx.closePath();

                ctx.fillStyle = Array.isArray(colors) ? colors[i % colors.length] : colors;
                ctx.fill();
                ctx.lineWidth = 2;
                ctx.strokeStyle = '#0B1F4A';
                ctx.stroke();

                startAngle = endAngle;
            }

            // Legend at bottom
            this.renderLegend(labels, colors, data);
        }

        renderBar() {
            const ctx = this.ctx;
            const labels = this.data.labels || [];
            const dataset = (this.data.datasets && this.data.datasets[0]) || { data: [] };
            const data = dataset.data || [];
            const colors = dataset.backgroundColor || '#00B4D8';

            const padLeft = 40;
            const padRight = 15;
            const padTop = 20;
            const padBottom = 45;
            const plotW = this.width - padLeft - padRight;
            const plotH = this.height - padTop - padBottom;

            const maxVal = Math.max(...data.map(v => Number(v) || 0), 5);
            const gridSteps = 4;

            // Draw Y Grid & labels
            ctx.font = '11px monospace';
            ctx.fillStyle = '#555';
            ctx.textAlign = 'right';
            ctx.textBaseline = 'middle';
            ctx.lineWidth = 1;

            for (let i = 0; i <= gridSteps; i++) {
                const y = padTop + (plotH / gridSteps) * (gridSteps - i);
                const val = Math.round((maxVal / gridSteps) * i);
                ctx.strokeStyle = '#e0dbce';
                ctx.beginPath();
                ctx.moveTo(padLeft, y);
                ctx.lineTo(this.width - padRight, y);
                ctx.stroke();
                ctx.fillText(String(val), padLeft - 6, y);
            }

            if (labels.length === 0) return;

            const barSlot = plotW / labels.length;
            const barW = Math.max(8, Math.min(barSlot * 0.6, 40));

            ctx.textAlign = 'center';
            ctx.textBaseline = 'top';

            for (let i = 0; i < labels.length; i++) {
                const val = Number(data[i]) || 0;
                const barH = (val / maxVal) * plotH;
                const x = padLeft + i * barSlot + (barSlot - barW) / 2;
                const y = padTop + plotH - barH;

                // Bar
                ctx.fillStyle = Array.isArray(colors) ? colors[i % colors.length] : colors;
                ctx.fillRect(x, y, barW, barH);
                ctx.lineWidth = 2;
                ctx.strokeStyle = '#0B1F4A';
                ctx.strokeRect(x, y, barW, barH);

                // Value above bar
                if (val > 0) {
                    ctx.font = 'bold 11px monospace';
                    ctx.fillStyle = '#0B1F4A';
                    ctx.fillText(String(val), x + barW / 2, y - 14);
                }

                // X label
                ctx.font = '10px monospace';
                ctx.fillStyle = '#333';
                let lbl = labels[i] || '';
                if (lbl.length > 7) lbl = lbl.substring(0, 6) + '…';
                ctx.fillText(lbl, x + barW / 2, padTop + plotH + 8);
            }
        }

        renderLine() {
            const ctx = this.ctx;
            const labels = this.data.labels || [];
            const dataset = (this.data.datasets && this.data.datasets[0]) || { data: [] };
            const data = dataset.data || [];
            const lineColor = dataset.borderColor || '#0B1F4A';
            const fillColor = dataset.backgroundColor || 'rgba(0, 180, 216, 0.2)';

            const padLeft = 40;
            const padRight = 20;
            const padTop = 20;
            const padBottom = 40;
            const plotW = this.width - padLeft - padRight;
            const plotH = this.height - padTop - padBottom;

            const maxVal = Math.max(...data.map(v => Number(v) || 0), 5);
            const gridSteps = 4;

            // Y Grid
            ctx.font = '11px monospace';
            ctx.fillStyle = '#555';
            ctx.textAlign = 'right';
            ctx.textBaseline = 'middle';
            ctx.lineWidth = 1;

            for (let i = 0; i <= gridSteps; i++) {
                const y = padTop + (plotH / gridSteps) * (gridSteps - i);
                const val = Math.round((maxVal / gridSteps) * i);
                ctx.strokeStyle = '#e0dbce';
                ctx.beginPath();
                ctx.moveTo(padLeft, y);
                ctx.lineTo(this.width - padRight, y);
                ctx.stroke();
                ctx.fillText(String(val), padLeft - 6, y);
            }

            if (data.length < 2) return;

            const stepX = plotW / (data.length - 1);
            const points = data.map((v, i) => {
                const val = Number(v) || 0;
                return {
                    x: padLeft + i * stepX,
                    y: padTop + plotH - (val / maxVal) * plotH
                };
            });

            // Fill area
            ctx.beginPath();
            ctx.moveTo(points[0].x, padTop + plotH);
            for (const pt of points) {
                ctx.lineTo(pt.x, pt.y);
            }
            ctx.lineTo(points[points.length - 1].x, padTop + plotH);
            ctx.closePath();
            ctx.fillStyle = fillColor;
            ctx.fill();

            // Line
            ctx.beginPath();
            ctx.moveTo(points[0].x, points[0].y);
            for (let i = 1; i < points.length; i++) {
                ctx.lineTo(points[i].x, points[i].y);
            }
            ctx.lineWidth = 2.5;
            ctx.strokeStyle = lineColor;
            ctx.stroke();

            // Dots
            for (const pt of points) {
                ctx.beginPath();
                ctx.arc(pt.x, pt.y, 4, 0, 2 * Math.PI);
                ctx.fillStyle = '#00B4D8';
                ctx.fill();
                ctx.lineWidth = 1.5;
                ctx.strokeStyle = '#0B1F4A';
                ctx.stroke();
            }

            // X axis labels (sparse)
            ctx.font = '9px monospace';
            ctx.fillStyle = '#444';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'top';
            const labelStep = Math.max(1, Math.floor(labels.length / 6));
            for (let i = 0; i < labels.length; i += labelStep) {
                ctx.fillText(labels[i] || '', points[i].x, padTop + plotH + 8);
            }
        }

        renderLegend(labels, colors, data) {
            const ctx = this.ctx;
            const y = this.height - 20;
            ctx.font = '10px monospace';
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';

            let currentX = 10;
            for (let i = 0; i < Math.min(labels.length, 5); i++) {
                const color = Array.isArray(colors) ? colors[i % colors.length] : colors;
                ctx.fillStyle = color;
                ctx.fillRect(currentX, y - 5, 10, 10);
                ctx.lineWidth = 1;
                ctx.strokeStyle = '#0B1F4A';
                ctx.strokeRect(currentX, y - 5, 10, 10);

                ctx.fillStyle = '#111';
                const txt = `${labels[i]}: ${data[i] || 0}`;
                ctx.fillText(txt, currentX + 14, y);
                currentX += ctx.measureText(txt).width + 22;
                if (currentX > this.width - 40) break;
            }
        }
    }

    global.Chart = Chart;
})(typeof window !== 'undefined' ? window : this);
